#include <bits/stdc++.h>using namespace std; int main() {    ios::sync_with_stdio(false);    cin.tie(NULL);     int t;    cin >> t;     while (t--) {        int n;        cin >> n;         vector<string> a(n);        for (int i = 0; i < n; i++) {            cin >> a[i];        }         vector<int> diag(n, 0); // count of 1s in each diagonal        int total_ones = 0;         // Count total ones and diagonal ones        for (int i = 0; i < n; i++) {            for (int j = 0; j < n; j++) {                if (a[i][j] == '1') {                    total_ones++;                    int d = (i - j + n) % n;                    diag[d]++;                }            }        }         int max_diag = 0;        for (int d = 0; d < n; d++) {            max_diag = max(max_diag, diag[d]);        }         // Minimum cost        int ans = total_ones + n - 2 * max_diag;         cout << ans << '\n';    }     return 0;}